import items from './items.json' with {type:'json'};

export async function listTools() {
  return [{
    name: 'catalog_search',
    description: 'Search the catalog by name (case-insensitive) with pagination.',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Search string matched against item names, case-insensitive.' },
        offset: { type: 'integer', description: 'Number of matches to skip. Defaults to 0.', default: 0 },
        limit: { type: 'integer', description: 'Maximum number of matches to return (1-5). Defaults to 2.', default: 2, minimum: 1, maximum: 5 }
      },
      required: ['query'],
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args = {}) {
  if (name !== 'catalog_search') {
    throw new Error(`Unknown tool: ${name}`);
  }
  // Validate args is an object
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }
  // Reject extra properties
  const allowed = ['query', 'offset', 'limit'];
  for (const k of Object.keys(args)) {
    if (!allowed.includes(k)) {
      throw new Error(`Unexpected argument: ${k}`);
    }
  }
  // query required, must be string
  if (!('query' in args)) {
    throw new Error('query is required');
  }
  const { query, offset = 0, limit = 2 } = args;
  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }
  if (!Number.isInteger(offset) || offset < 0) {
    throw new Error('offset must be a non-negative integer');
  }
  if (!Number.isInteger(limit) || limit < 1 || limit > 5) {
    throw new Error('limit must be an integer between 1 and 5');
  }
  // search case-insensitive
  const q = query.toLowerCase();
  const matches = items.filter(it => it.name.toLowerCase().includes(q));
  const slice = matches.slice(offset, offset + limit);
  const more = offset + limit < matches.length;
  const result = {
    items: slice,
    count: slice.length,
    total: matches.length
  };
  if (more) {
    result.next_offset = offset + limit;
  }
  return {
    content: [{ type: 'text', text: JSON.stringify(result) }]
  };
}
